from lib89 import *
def B(ch,tn,*a,**k): build('social-science',ch,tn,*a,**k)
B(1,'What is Social Science','Understanding social science','Why do we study society?',
 "Human beings live in societies and depend on each other. Our lives are shaped by the past, by the land and weather around us, by the rules we follow and by how we earn and spend. Social science studies all these together.",
 [("In Grades 6 to 8 we explored social science through stories of people, places and events. In Grade 9 we pause to understand what social science truly means.","social science"),
  ("Human beings live in societies and depend on each other in many ways, so the study of society needs more than one point of view.","society"),
  ("History studies how people and societies changed over time, using sources such as inscriptions, coins and books.","history"),
  ("Geography studies the Earth, its landforms, climate and resources, and how people live with them.","geography"),
  ("Political science studies power, rules, government and citizens' rights and duties.","political science"),
  ("Economics studies how people produce, exchange and use goods and services when resources are limited.","economics"),
  ("These disciplines are connected. For example, a monsoon failure (geography) affects farm incomes (economics), government relief (political science) and migration (history).","connected disciplines"),
  ("Social science teaches us to ask questions, look at evidence and respect different views.","skills")],
 ("Show how a drought links all four social sciences.",[("Geography: rainfall fails and crops dry.","Cause."),("Economics: farmers lose income and prices rise.","Effect."),("Political science: government announces relief; history shows earlier famines.","Response and memory.")]),
 ("Name the four disciplines and the main question each asks.",["History: how did things change","Geography: where and why","Economics and political science: resources and power"],["Thinking they are unrelated subjects"]),
 ["Social science studies people in society.","History, geography, political science and economics are its main branches.","The branches are connected.","It builds questioning and evidence-based thinking."],
 [mcq("ss1-1",1,"Which discipline studies how people change over time?","History",["Geography","Economics"],"History studies the past."),
  mcq("ss1-2",1,"Which studies production, exchange and use of goods?","Economics",["History","Civics only"],"That is economics."),
  tf("ss1-3",1,"The branches of social science are unrelated.",False,"They are closely connected."),
  mcq("ss1-4",2,"Rules, power and government are studied in","political science",["geography","botany"],"Political science."),
  mcq("ss1-5",2,"Landforms and climate are studied in","geography",["history","economics"],"Geography."),
  tf("ss1-6",2,"Evidence matters in social science.",True,"We ask questions and use evidence."),
  short("ss1-7",3,"Name any one source historians use.",["inscriptions","coins","books","manuscripts"],"Inscriptions, coins and books are sources."),
  mcq("ss1-8",3,"A monsoon failure affects farm incomes. This links geography with","economics",["chemistry","music"],"Income is an economic matter.")])
B(2,'Plate tectonics and landforms','Shaping of the Earth\'s surface: plate tectonics and landforms','The moving surface',
 "The Earth's surface looks still, yet continents drift by a few centimetres every year. Over millions of years this slow movement builds mountains and opens oceans.",
 [("The Earth's surface is shaped by forces from inside, called endogenic, and forces from outside, called exogenic.","endogenic and exogenic"),
  ("According to plate tectonics, the lithosphere is broken into large and small plates that move slowly over the softer layer below.","plate tectonics"),
  ("At plate boundaries plates may move apart, collide or slide past each other. These movements cause earthquakes, volcanoes and mountain building.","plate movements"),
  ("Landforms are natural features such as mountains, plateaus and plains. They are classified by height and shape.","landforms"),
  ("Weathering breaks rocks, and erosion carries the pieces away by water, wind and ice. Deposition builds new landforms such as deltas.","weathering, erosion, deposition"),
  ("Landforms influence where humans and other living beings live: rivers and plains support farming, and mountains support forests and pastoralism.","landforms and life"),
  ("Disasters like earthquakes, landslides and volcanic eruptions can harm people, so preparedness matters.","disasters"),
  ("Understanding landforms helps us plan settlements and protect lives.","planning")],
 ("Explain how mountains form where two plates collide.",[("Two plates move towards each other.","Convergent boundary."),("Rocks between them are squeezed and folded upwards.","Folding."),("This slowly raises a mountain range like the Himalaya.","Result.")]),
 ("How do internal and external forces shape the Earth?",["Plate movements build","Weathering and erosion wear down","Deposition creates new landforms"],["Thinking continents never move"]),
 ["Plates of the lithosphere move slowly.","Plate movement causes earthquakes, volcanoes and mountains.","Erosion and deposition shape landforms.","Landforms influence human life."],
 [mcq("ss2-1",1,"The Earth's rigid outer layer broken into plates is the","lithosphere",["atmosphere","hydrosphere"],"Plates make up the lithosphere."),
  tf("ss2-2",1,"Continents move very slowly.",True,"A few centimetres per year."),
  mcq("ss2-3",2,"The carrying away of broken rock by water or wind is","erosion",["weathering","convection"],"Erosion removes material."),
  mcq("ss2-4",2,"A delta is formed by","deposition",["volcano","earthquake"],"Rivers deposit sediments."),
  mcq("ss2-5",2,"Mountain ranges often form where plates","collide",["stay still","separate only"],"Collision folds the crust."),
  tf("ss2-6",2,"Earthquakes can occur at plate boundaries.",True,"Movement releases energy."),
  short("ss2-7",3,"Name a mountain range formed by plate collision.",["himalaya","himalayas","alps"],"The Himalaya."),
  mcq("ss2-8",3,"Wearing down of rocks in place is called","weathering",["deposition","tectonics"],"Weathering breaks rocks.")])
B(3,'Atmosphere and climate','Atmosphere, climate and the monsoon','The blanket of air',
 "Look up: sun, clouds, a breeze. The air around the Earth is a thin but vital blanket. It gives us oxygen, controls temperature and brings the monsoon rains.",
 [("The atmosphere is made mainly of nitrogen, about 78 percent, and oxygen, about 21 percent, with small amounts of argon, carbon dioxide and water vapour.","composition"),
  ("It has layers: troposphere, stratosphere, mesosphere, thermosphere and exosphere. Weather happens in the troposphere.","layers"),
  ("The ozone layer in the stratosphere absorbs harmful ultraviolet rays from the Sun.","ozone layer"),
  ("Weather is the day-to-day state of the atmosphere; climate is its average over a long time.","weather and climate"),
  ("Temperature, pressure, winds, humidity and rainfall are the elements of weather and climate.","elements"),
  ("The monsoon is a seasonal reversal of winds. In summer, moist winds from the sea blow towards heated land and bring rain.","monsoon"),
  ("Burning fuels adds carbon dioxide and raises the carbon footprint, the total greenhouse gases we cause.","carbon footprint"),
  ("We can reduce it by saving energy, using public transport, planting trees and avoiding waste.","reduce footprint")],
 ("Why does the monsoon bring rain to India in summer?",[("Land heats faster than the sea, so air over land rises.","Low pressure."),("Moist air from the ocean rushes in.","Winds reverse."),("It rises, cools and falls as rain.","Condensation.")]),
 ("Differentiate weather from climate and name the layers of the atmosphere.",["Short term vs long term","Five layers","Ozone absorbs UV"],["Using the words as the same thing"]),
 ["The air is mostly nitrogen and oxygen.","Weather is short-term; climate is long-term.","Monsoon winds reverse with the season.","We can reduce our carbon footprint."],
 [mcq("ss3-1",1,"The gas making up most of the atmosphere is","nitrogen",["oxygen","carbon dioxide"],"About 78 percent."),
  mcq("ss3-2",1,"Weather occurs in the","troposphere",["exosphere","mesosphere"],"The lowest layer."),
  tf("ss3-3",1,"Climate is the average weather over a long time.",True,"Yes."),
  mcq("ss3-4",2,"The ozone layer absorbs","ultraviolet rays",["sound","gravity"],"It protects living things."),
  mcq("ss3-5",2,"Monsoon winds in summer blow","from sea to land",["from land to sea","only at night"],"They carry moisture."),
  tf("ss3-6",2,"Planting trees can reduce carbon footprint.",True,"Trees absorb carbon dioxide."),
  short("ss3-7",3,"Name the lowest layer of the atmosphere.",["troposphere"],"The troposphere."),
  mcq("ss3-8",3,"A way to reduce carbon footprint is","using public transport",["burning waste","wasting energy"],"Less fuel is burned.")])
B(4,'Early humans and civilisations','Early humans and the beginning of civilisation','From caves to cities',
 "Thousands of years ago there were no books, no cities and no writing. How do we know about those people? Stones, bones, paintings and ruins tell the story.",
 [("Early humans lived by hunting animals and gathering plants. They made tools of stone and later learned to use fire.","hunter-gatherers"),
  ("Before writing, people communicated through gestures, speech, cave paintings and symbols.","before writing"),
  ("Archaeology studies the past from material remains such as tools, pottery, bones and ruins.","archaeology"),
  ("Farming and animal rearing led to settled villages, a big change in human life.","settled life"),
  ("Early civilisations grew along rivers, such as the Indus in the Indian subcontinent, the Nile in Egypt and the Tigris and Euphrates in Mesopotamia.","river valley civilisations"),
  ("Their cities had planned streets, drains, trade and craft work. Writing was invented to keep records.","features of civilisation"),
  ("Civilisations interacted through trade. Indus beads and seals have been found in Mesopotamia.","trade links"),
  ("Understanding the past helps us see how ideas and technologies spread across the world.","importance")],
 ("Explain how archaeologists learn about people who left no writing.",[("They dig and study tools, pottery and houses.","Material remains."),("They date objects and compare them across sites.","Evidence."),("They then reconstruct how people lived.","Interpretation.")]),
 ("Why did early civilisations grow near rivers?",["Water and fertile soil","Farming surplus","Trade routes"],["Thinking all early humans lived in cities"]),
 ["Early humans hunted and gathered.","Farming led to settled life and cities.","Archaeology studies material remains.","Early civilisations traded with each other."],
 [mcq("ss4-1",1,"Archaeologists study the past using","material remains",["only books","only maps"],"Tools, pottery, ruins."),
  mcq("ss4-2",1,"Early civilisations mostly grew near","rivers",["deserts only","mountain tops"],"River valleys gave water and fertile land."),
  tf("ss4-3",1,"Early humans lived by hunting and gathering.",True,"Before farming."),
  mcq("ss4-4",2,"The Indus civilisation flourished in the","Indian subcontinent",["Americas","Antarctica"],"Harappa and Mohenjo-daro."),
  mcq("ss4-5",2,"Writing was invented to","keep records",["stop farming","build roads only"],"Records of trade and tax."),
  tf("ss4-6",2,"Indus seals have been found in Mesopotamia.",True,"This shows trade."),
  short("ss4-7",3,"Name one river valley civilisation.",["indus","nile","mesopotamia","egypt"],"Indus, Nile or Tigris-Euphrates."),
  mcq("ss4-8",3,"Before writing, people communicated by","cave paintings and symbols",["email","telephone"],"They used images and speech.")])
B(5,'State and society up to 1000 CE','State and society in the Indian subcontinent up to 1000 CE','Kings, dharma and the idea of one land',
 "More than a thousand years ago, rulers across the subcontinent governed in many different ways. Yet ideas such as dharma and the chakravarti samrat helped people see the land as one cultural whole.",
 [("Early states in the subcontinent grew from janapadas into larger mahajanapadas, with kings, taxes and armies.","janapadas to mahajanapadas"),
  ("The Mauryan empire under Chandragupta and Ashoka brought much of the subcontinent under one rule.","Mauryan empire"),
  ("Ashoka's edicts spread the idea of dhamma, which stressed non-violence, tolerance and care for people.","Ashoka's dhamma"),
  ("The Gupta period is remembered for advances in mathematics, astronomy, literature and art.","Gupta age"),
  ("Dharma meant duty and right conduct, and kings were expected to rule by dharma.","dharma"),
  ("A chakravarti samrat was a ruler who aimed to unite regions under one wide authority, promoting a shared political idea.","chakravarti samrat"),
  ("Society was organised in villages, guilds and learning centres like Nalanda; trade linked the subcontinent with other lands.","society and trade"),
  ("Southern kingdoms like the Cholas and Pallavas built strong states, temples and sea trade.","southern kingdoms")],
 ("Why are Ashoka's edicts important sources?",[("They were carved on rocks and pillars in public places.","Durable record."),("They tell us about his policies and values.","Primary source."),("They are found across the subcontinent.","Wide reach.")]),
 ("How did dharma and the idea of the chakravarti help unity?",["Shared values","Rule by duty","Wider political idea"],["Thinking the subcontinent had one ruler throughout"]),
 ["Early states grew from janapadas.","Mauryas and Guptas built large states.","Dharma guided kings and society.","Trade and learning linked regions."],
 [mcq("ss5-1",1,"Ashoka's edicts spread the idea of","dhamma",["conquest only","tax only"],"Non-violence and tolerance."),
  mcq("ss5-2",1,"Larger early kingdoms were called","mahajanapadas",["villages","guilds"],"They grew from janapadas."),
  tf("ss5-3",1,"Kings were expected to rule by dharma.",True,"Duty and right conduct."),
  mcq("ss5-4",2,"The Gupta age is known for","advances in mathematics and astronomy",["no progress","only wars"],"A period of learning."),
  mcq("ss5-5",2,"Nalanda was a centre of","learning",["war","salt trade only"],"A famed university."),
  tf("ss5-6",2,"The Cholas built strong states and temples.",True,"They ruled in the south."),
  short("ss5-7",3,"Name the Mauryan emperor associated with dhamma.",["ashoka"],"Ashoka."),
  mcq("ss5-8",3,"A chakravarti samrat was a ruler who","aimed to unite regions",["lived in a forest","gave up the throne"],"A wide authority.")])
